<script>document.addEventListener('DOMContentLoaded',()=>{const box=document.getElementById('options');let i=box.querySelectorAll('.option-row').length;document.getElementById('addOption').onclick=()=>{if(box.children.length>=20)return;box.insertAdjacentHTML('beforeend',`<div class="input-group mb-2 option-row"><span class="input-group-text"><i class="far fa-circle"></i></span><input name="options[${i++}][option_text]" class="form-control" required maxlength="255"><button type="button" class="btn btn-outline-danger remove-option"><i class="fas fa-times"></i></button></div>`)};box.onclick=e=>{const b=e.target.closest('.remove-option');if(!b)return;if(box.querySelectorAll('.option-row').length<=2)return alert('At least two options are required.');b.closest('.option-row').remove()}});</script>
